import { $applyNodeReplacement, $createParagraphNode, $insertNodes, $isRootOrShadowRoot, $parseSerializedNode, } from "lexical";
import { $wrapNodeInElement } from "@lexical/utils";
export const $createNodeFromSerializedNode = (serializedNode) => {
    return $applyNodeReplacement($parseSerializedNode(serializedNode));
};
export const $insertUsfmNode = (serializedNode) => {
    const newNode = $createNodeFromSerializedNode(serializedNode);
    $insertNodes([newNode]);
    if ($isRootOrShadowRoot(newNode.getParentOrThrow())) {
        $wrapNodeInElement(newNode, $createParagraphNode).selectEnd();
    }
    return newNode;
};
